-- Migration 999m: SARS IRP5/IT3(a) source codes for the 2024 and 2025 years of assessment.
--
-- Production still held the 19-row legacy seed for both years (wrong meanings for 4003-4005, no 4006, no 3696-3699),
-- so IRP5_UNKNOWN_CODE fired on real codes. These are the full sets from the SARS PAYE Employer Reconciliation BRS
-- (section 6.5-6.7), built into the two workbooks under scripts/data/sars-codes/. isaflow_app has no access to these
-- tables, so the deploy role applies them. GENERATED by scripts/emit-sars-codes-migration.ts; do not edit by hand
-- (tests/unit/scripts/sarsCodesMigration.test.ts regenerates it and diffs).
--
-- Idempotent: a row is rewritten only when its content differs, so a second run changes nothing. Data only, no DDL,
-- no DELETE: the old colour keeps working while it runs. sars_code_releases.is_current is never touched.
-- Rollback: the previous rows cannot be restored from the app role; they were the legacy seed (19 rows per year).
-- After rolling back past 999m, restart both colours (bash scripts/deploy/restart-colours.sh): sarsCodesService
-- caches each year it has read, so a running colour keeps serving that year until restarted.

-- 2024: 129 codes, BRS v22.1.2
ON CONFLICT (code, effective_year) DO UPDATE SET
  category = EXCLUDED.category,
  description = EXCLUDED.description,
  status = EXCLUDED.status,
  foreign_code = EXCLUDED.foreign_code,
  code_pair = EXCLUDED.code_pair,
  applicability_note = EXCLUDED.applicability_note,
  rationalisation_note = EXCLUDED.rationalisation_note,
  source_document = EXCLUDED.source_document,
  source_url = EXCLUDED.source_url,
  official_excerpt = EXCLUDED.official_excerpt,
  brs_version = EXCLUDED.brs_version,
  imported_at = now()
WHERE (sars_source_codes.category, sars_source_codes.description, sars_source_codes.status, sars_source_codes.foreign_code, sars_source_codes.code_pair, sars_source_codes.applicability_note, sars_source_codes.rationalisation_note, sars_source_codes.source_document, sars_source_codes.source_url, sars_source_codes.official_excerpt, sars_source_codes.brs_version) IS DISTINCT FROM (EXCLUDED.category, EXCLUDED.description, EXCLUDED.status, EXCLUDED.foreign_code, EXCLUDED.code_pair, EXCLUDED.applicability_note, EXCLUDED.rationalisation_note, EXCLUDED.source_document, EXCLUDED.source_url, EXCLUDED.official_excerpt, EXCLUDED.brs_version);

-- 2025: 131 codes, BRS v23.0.0
ON CONFLICT (code, effective_year) DO UPDATE SET
  category = EXCLUDED.category,
  description = EXCLUDED.description,
  status = EXCLUDED.status,
  foreign_code = EXCLUDED.foreign_code,
  code_pair = EXCLUDED.code_pair,
  applicability_note = EXCLUDED.applicability_note,
  rationalisation_note = EXCLUDED.rationalisation_note,
  source_document = EXCLUDED.source_document,
  source_url = EXCLUDED.source_url,
  official_excerpt = EXCLUDED.official_excerpt,
  brs_version = EXCLUDED.brs_version,
  imported_at = now()
WHERE (sars_source_codes.category, sars_source_codes.description, sars_source_codes.status, sars_source_codes.foreign_code, sars_source_codes.code_pair, sars_source_codes.applicability_note, sars_source_codes.rationalisation_note, sars_source_codes.source_document, sars_source_codes.source_url, sars_source_codes.official_excerpt, sars_source_codes.brs_version) IS DISTINCT FROM (EXCLUDED.category, EXCLUDED.description, EXCLUDED.status, EXCLUDED.foreign_code, EXCLUDED.code_pair, EXCLUDED.applicability_note, EXCLUDED.rationalisation_note, EXCLUDED.source_document, EXCLUDED.source_url, EXCLUDED.official_excerpt, EXCLUDED.brs_version);

ON CONFLICT (effective_year) DO UPDATE SET
  brs_version = EXCLUDED.brs_version, released_at = EXCLUDED.released_at, notes = EXCLUDED.notes
WHERE (sars_code_releases.brs_version, sars_code_releases.released_at, sars_code_releases.notes)
  IS DISTINCT FROM (EXCLUDED.brs_version, EXCLUDED.released_at, EXCLUDED.notes);

