INSERT INTO sars_source_codes (code, effective_year, category, description, status, foreign_code, code_pair, applicability_note, rationalisation_note, source_document, source_url, official_excerpt, brs_version) VALUES
  ('3601', 2024, 'income', 'Income excluding any Long Service Cash Award, required to be declared under code (Subject to PAYE)', 'conditional', '3651', '3601/3651', 'Applicable from 2010 to 2019 years of assessment for amounts', '*3603/3653 and *3610/3660 must be incorporated into 3601/3651. * Only in respect of 2010 to 2012 years of assessment. Codes 3604/3654, 3609/3659 and 3612/3662 must be incorporated into', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• An amount which is paid or payable to an employee for services rendered, 3622/3672. • Examples include: ▫ Salary/wages; ▫ Backdated salary/wages/pension (Accrued in current year of assessment). ▫ Remuneration paid to migrant/seasonal workers/full time scholars etc. Note: ▫ For Years of Assessment 2003 to 2018, such income as paid to a director must be reflected under code 3615; ▫ Use code 3651 ONLY for foreign services income. ▫ Applicable from 2010 to 2019 years of assessment for amounts prev', 'v22.1.2'),
  ('3602', 2024, 'income', 'Non-Taxable Income (Excl)', 'conditional', '3652', '3602/3652', 'Main code from the 2013 year of assessment', 'Main code from the 2013 year of assessment. From 2026 year of', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Any non-taxable income excluding Foreign Service remuneration for RSA .e., section 10(1)(o)(ii), non-taxable allowances and fringe benefits. This code accommodates all payments of a capital nature. • Examples include: ▫ Non-taxable pension paid on a regular basis (e.g., war pension, etc.) excluding pension for Foreign Service income. ▫ Non-taxable income of a capital nature ▫ Non-taxable portion of an arbitration award, where applicable. ▫ Non-taxable portion of a compulsory annuity purchased', 'v22.1.2'),
  ('3603', 2024, 'income', 'Pension (PAYE)', 'conditional', '3653', '3603/3653', 'valid from 1999 – 2009 year of assessment and from the assessment, a directive may be issued for the source code', 'assessment, a directive may be issued for the source code.', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Any compulsory pension or qualifying purchased annuity paid on a regular pension or compulsory purchased annuity payment (from a pension or pension preservation fund) (for current tax year). Note: ▫ Amounts paid on a regular basis i.e., a Loss of Income Policy up to 28 February 2015 (up to the 2015 year of assessment). ▫ Use code 3653 ONLY for foreign services income taxable in RSA. ▫ The value of this code must be included in the value of code 3601/3651 for the 2010, 2011 and 2012 years of as', 'v22.1.2'),
  ('3604', 2024, 'income', 'Pension (Non-taxable)', 'deprecated', '3654', '3604/3654', 'applicable from 2010 Year of Assessment | Not applicable from 2010 Year of Assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Any pension paid on regular basis that is not taxable e.g., War pensions etc. Note: ▫ Use code 3654 ONLY for foreign services income. ▫ The value of this code must be included in the value of code 3602/3652 with effect from the 2010 year of assessment. ▫ Not applicable from 2010 Year of Assessment', 'v22.1.2'),
  ('3605', 2024, 'income', 'Annual payment (PAYE)', 'conditional', '3655', '3605/3655', 'Applicable from 2003 to 2018 years of assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Amount paid or payable to employee, which is defined as an annual under code 3622/3672. • Examples include: ▫ Annual bonus; ▫ Incentive bonus; ▫ Leave pay (on resignation/encashment of leave credits). ▫ Merit awards; ▫ Bonus/incentive amount paid to an employee to retain his/her service for a specific period; etc. Note: ▫ Use code 3655 ONLY for foreign services income. ▫ Applicable from 2003 to 2018 years of assessment.', 'v22.1.2'),
  ('3606', 2024, 'income', 'Commission (Subject to PAYE)', 'active', '3656', '3606/3656', NULL, 'Main code for years prior to 2010 year of assessment and from 2020 years of', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• An amount paid or payable to an employee defined as an annual payment. Note: ▫ Use code 3656 ONLY for foreign services income. Effective Date: 19 September 2025', 'v22.1.2'),
  ('3607', 2024, 'income', 'Overtime payments is calculated as on income taxable (Subject to PAYE)', 'active', '3657', '3607/3657', NULL, 'assessment. Incorporate codes into 3601/3651 in respect 2010 to 2019 years of assessment.', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• An amount paid as overtime for rendering services. The tax on such . Note: ▫ Use code 3657 ONLY for foreign services income; ▫ The value of this code must be included in the value of code 3601/3651 with effect from the 2010 to 2019 year of assessment. ▫ This code is applicable prior to 2010 year of assessment and from 2020 year of assessment.', 'v22.1.2'),
  ('3608', 2024, 'income', 'Arbitration award (Subject to PAYE)', 'conditional', '3658', '3608/3658', 'Main code from the 2013 year of assessment', 'Main code from the 2013 year of assessment. Incorporate codes into', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• The taxable portion of a settlement agreement between an employer and an employee as ordered by Court or allocated via a settlement out of Court or in respect of Labour disputes. Note: ▫ Use code 3658 ONLY for foreign services income.', 'v22.1.2'),
  ('3609', 2024, 'income', 'Arbitration award and an employee as ordered by Court (Non-taxable)', 'active', '3659', '3609/3659', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• The non-taxable portion of a settlement agreement between an employer . Also including all awards allocated via a settlement out of Court or in respect of Labour disputes. Note: ▫ Use code 3659 ONLY for foreign services income; ▫ The value of this code must be included in the value of code 3602/3652 with effect from the 2010 year of assessment.', 'v22.1.2'),
  ('3610', 2024, 'income', 'Annuity from a RAF (PAYE)', 'conditional', '3660', '3610/3660', 'valid from the 2002 | Valid for 1999 to 2009 and from the 2013 years of assessment', '3601/3651 in respect 2010 to 2012 years of assessment. From 2026 year of assessment, a directive may be issued for the source code.', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• An annuity paid on a regular basis by a retirement annuity fund and/or a (Subject to PAYE) on a regular basis. Note: ▫ Use code 3660 ONLY for foreign services income; ▫ The value of this code must be included in the value of code 3601/3651 with effect from the 2010 to 2012 years of assessment. ▫ Valid for 1999 to 2009 and from the 2013 years of assessment. The Foreign Service income codes (codes in brackets) are valid from the 2002 to 2009 and from the 2013 years of assessment ▫ From the 2026', 'v22.1.2'),
  ('3611', 2024, 'income', 'Purchased annuity (PAYE)', 'active', '3661', '3611/3661', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• The taxable portion of a purchased annuity paid by a long-term insurer (not . (Subject to PAYE) Note: ▫ Use code 3661 ONLY for foreign services income.', 'v22.1.2'),
  ('3612', 2024, 'income', 'Purchased annuity from an Annuity Fund', 'active', '3662', '3612/3662', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• The non-taxable portion (capital interest) received on an annuity purchased . (Non-taxable) Note: ▫ Use code 3662 ONLY for foreign services income; ▫ The value of this code must be included in the value of code 3602/3652 with effect from the 2010 year of assessment.', 'v22.1.2'),
  ('3613', 2024, 'income', 'Restraint of trade (Subject to PAYE)', 'active', '3663', '3613/3663', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Restraint of trade amount paid by virtue of employment or the holding of any office to an employee who is a natural person [par (cB) of ‘gross income’]. Note: ▫ Restraint of trade amounts paid to a labour broker must NOT be included under this code. ▫ Use code 3663 ONLY for Foreign Service income. Effective Date: 19 September 2025', 'v22.1.2'),
  ('3614', 2024, 'income', 'Other retirement lump sums', 'active', '3664', '3614/3664', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• A retirement lump sum paid by a fund [par (eA) of ‘gross income’] (Subject to PAYE) Note: ▫ Use code 3664 ONLY for foreign services income.', 'v22.1.2'),
  ('3615', 2024, 'income', 'Director’s remuneration to a director of a private company/member of a close corporation', 'conditional', '3665', '3615/3665', 'applicable from 2003 to 2018 years of assessment | Applicable from 2003 to 2018 years of assessment', 'Applicable from 2003 to 2018 years of assessment.', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Such income as would normally be reported under code 3601/3651 as paid . (Subject to PAYE) Note: ▫ Use code 3615/3665 ONLY if Nature of Person is C. ▫ Use code 3665 ONLY for foreign services income. ▫ This code is applicable from 2003 to 2018 years of assessment. ▫ Effective from 2019 year of assessment, report such income under code 3601/3651.', 'v22.1.2'),
  ('3616', 2024, 'income', 'Independent contractors', 'active', '3666', '3616/3666', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Remuneration paid to an independent contractor. (Subject to PAYE) Note: ▫ Use code 3666 ONLY for foreign services income.', 'v22.1.2'),
  ('3617', 2024, 'income', 'Labour Brokers (PAYE)', 'active', '3667', '3617/3667', NULL, 'Effective Date: 19 September 2025 Type of Income Main Code Sub-Code Rationalisation', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Remuneration, including a Restraint of trade amount [par (cA) of ‘gross . Note: ▫ Use code 3667 ONLY for foreign services income', 'v22.1.2'),
  ('3618', 2024, 'income', 'Annuity from Provident/Provident Preservation Fund (PAYE)', 'conditional', '3668', '3618/3668', 'applicable from the 2021 year of assessment Applicable from the 2021 year of assessment', 'Applicable from the 2021 year of assessment', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Any qualifying annuity paid on a regular basis from a provident or provident Provident / preservation fund as well as backdated provident or qualifying annuity (from Provident a provident or provident preservation fund) (for current tax year). Preservation Fund (PAYE) Note: ▫ Use code 3668 ONLY for foreign service income. ▫ This code is applicable from the 2021 year of assessment', 'v22.1.2'),
  ('3619', 2024, 'income', 'Labour Brokers', 'conditional', NULL, '3619', 'applicable from the 2017 year of assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Any amount, including a Restraint of trade amount, paid to a labour broker (3669) (IT) who is in possession of an exemption certificate (IRP 30). Note: ▫ Use code 3669 ONLY for foreign service income ▫ This code is applicable from the 2017 year of assessment.', 'v22.1.2'),
  ('3620', 2024, 'income', 'Directors Fees – RSA Resident NED (IT)', 'conditional', '3670', '3620/3670', 'applicable from 2018 year of assessment | Main code from the 2018 year of assessment', 'Main code from the 2018 year of assessment', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• Directors’ fees / Audit Committee Members fees received by an RSA Non- . Committee • Fees (not remuneration) received by the Audit Committee Member who is Members Fees – deemed to be carrying on a trade independently in terms of the Interpretation RSA Resident Note 17. (IT) Note: ▫ Use code 3670 ONLY for foreign service income ▫ Only applicable from 2018 year of assessment.', 'v22.1.2'),
  ('3621', 2024, 'income', 'Directors Remuneration – Non-Resident NED (PAYE)', 'conditional', NULL, '3621', 'applicable from 2018 year of assessment | Main code from the 2018 year of assessment', 'Main code from the 2018 year of assessment', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', 'Non- Resident • Directors’ remuneration received from an RSA source by a Non-Resident NED Non-Executive Director (PAYE) Note: ▫ Only applicable from 2018 year of assessment. Effective Date: 19 September 2025', 'v22.1.2'),
  ('3622', 2024, 'income', 'Long Service', 'conditional', '3672', '3622/3672', 'Applicable from the 2023 year of assessment', 'Applicable from the 2023 year of assessment', 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE-AE-06-G06 (Guide for Codes Applicable to Employees Tax Certificates 2026) 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', '• A Long Service Award is given to an employee that complies with the initial Cash Award 15 years and any subsequent 10 years unbroken period of service requirement – par (vii) of the proviso under par (c) of “gross income” in section 1 of the Income Tax Act. Note: ▫ The full value (before excluding any amount) of a Long Service Cash Award that qualify for the R5,000 exclusion, must be declared under this code 3622/3672. The amount is not subject to PAYE if the full value (code', 'v22.1.2'),
  ('3696', 2024, 'income', 'Gross non-taxable income (amounts under codes 3602/3652, 3622/3672 (Excl), 3703/3753, 3714/3764, 3815/3865, 3830/3880, 3832/3882, 3834/3884, 3835/3885 (Excl), 3821/3871, 3822/3872, 3908, 3922 (Excl))', 'active', NULL, '3696', NULL, NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE BRS - PAYE Employer Reconciliation V25.2.0 (Apr-26), section 6.5-6.7, PDF p.101 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', 'Gross non-taxable income (amounts under codes 3602/3652, 3622/3672 (Excl), 3703/3753, 3714/3764, 3815/3865, 3830/3880, 3832/3882, 3834/3884, 3835/3885 (Excl), 3821/3871, 3822/3872, 3908, 3922 (Excl))', 'v22.1.2'),
  ('3697', 2024, 'income', 'Gross retirement funding employment income', 'deprecated', NULL, '3697', 'Not applicable from the 2017 year of assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE BRS - PAYE Employer Reconciliation V25.2.0 (Apr-26), section 6.5-6.7, PDF p.101 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', 'Gross retirement funding employment income. Not applicable from the 2017 year of assessment', 'v22.1.2'),
  ('3698', 2024, 'income', 'Gross non-retirement funding employment income', 'deprecated', NULL, '3698', 'Not applicable from the 2017 year of assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE BRS - PAYE Employer Reconciliation V25.2.0 (Apr-26), section 6.5-6.7, PDF p.101 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', 'Gross non-retirement funding employment income. Not applicable from the 2017 year of assessment', 'v22.1.2'),
  ('3699', 2024, 'income', 'Gross employment income (taxable): amounts for all income source codes NOT included in code 3696', 'conditional', NULL, '3699', 'Not applicable from the 2010 to 2016 years of assessment', NULL, 'SARS PAYE BRS - PAYE Employer Reconciliation V22.1.2 (effective 1 March 2023; PDF sha256 e3f915d0825e7a48a778df0f3b85031dc4e184693438234eb58bfd2a3a21649f); row text carried from the SARS PAYE BRS - PAYE Employer Reconciliation V25.2.0 (Apr-26), section 6.5-6.7, PDF p.101 2026 list (no change in meaning for this code)', 'https://www.sars.gov.za/wp-content/uploads/Docs/PAYE/BRS/SARS_PAYE_BRS-PAYE-Employer-Reconciliation_V22-1-2.pdf', 'Gross employment income (taxable): amounts for all income source codes NOT included in code 3696. Not applicable from the 2010 to 2016 years of assessment', 'v22.1.2'),
